{"pou_name":"MotorStartStop","pou_type":"FUNCTION_BLOCK","declaration":"FUNCTION_BLOCK MotorStartStop
VAR_INPUT
    StartBtn : BOOL;
    StopBtn : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Motor : BOOL;
END_VAR","implementation":"IF StopBtn OR EStop THEN
    Motor := FALSE;
ELSIF StartBtn THEN
    Motor := TRUE;
END_IF;"}
